import itertools

def get_all_2x2_blocks(n):
    blocks = []
    for i in range(n - 1):
        for j in range(n - 1):
            blocks.append(((i, j), (i + 1, j), (i, j + 1), (i + 1, j + 1)))
    return blocks

def apply_rules(grid, n):
    blocks = get_all_2x2_blocks(n)
    changed = True
    reachable = {tuple(grid)}
    queue = [tuple(grid)]

    idx = 0
    while idx < len(queue):
        curr_grid = list(queue[idx])
        idx += 1

        for block in blocks:
            cells = [curr_grid[r * n + c] for r, c in block]
            s = sum(cells)

            if s == 3:
                # Rule 1: the sterile section gets infected
                new_grid = list(curr_grid)
                for r, c in block:
                    if new_grid[r * n + c] == 0:
                        new_grid[r * n + c] = 1
                t_grid = tuple(new_grid)
                if t_grid not in reachable:
                    reachable.add(t_grid)
                    queue.append(t_grid)

            elif s == 2:
                # Rule 2: infected sections become sterile, and sterile sections become infected
                new_grid = list(curr_grid)
                for r, c in block:
                    new_grid[r * n + c] = 1 - new_grid[r * n + c]
                t_grid = tuple(new_grid)
                if t_grid not in reachable:
                    reachable.add(t_grid)
                    queue.append(t_grid)
    return reachable

def check_k(n, k):
    # Try all possible initial configurations of k infected sections
    # This is too many for n=3, k=4. Let's try small n.
    import itertools
    for config in itertools.combinations(range(n * n), k):
        grid = [0] * (n * n)
        for cell in config:
            grid[cell] = 1

        reachable = apply_rules(grid, n)
        if tuple([1] * (n * n)) not in reachable:
