import collections

def get_all_2x2_masks(n):
    masks = []
    for i in range(n - 1):
        for j in range(n - 1):
            mask = (1 << (i * n + j)) | (1 << ((i + 1) * n + j)) | \
                   (1 << (i * n + j + 1)) | (1 << ((i + 1) * n + j + 1))
            masks.append(mask)
    return masks

def solve_reachability(initial_mask, n, blocks):
    visited = {initial_mask}
    queue = collections.deque([initial_mask])
    target = (1 << (n * n)) - 1

    while queue:
        curr = queue.popleft()
        if curr == target:
            return True

        for mask in blocks:
            # Count bits in the intersection of curr and mask
            bits = bin(curr & mask).count('1')
            if bits == 3:
                # Rule 1: the sterile section becomes infected
                next_mask = curr | mask
                if next_mask not in visited:
                    visited.add(next_mask)
                    queue.append(next_mask)
            elif bits == 2:
                # Rule 2: flip all 4 sections
                next_mask = curr ^ mask
                if next_mask not in visited:
                    visited.add(next_mask)
                    queue.append(next_mask)
    return False

def check_k_bitmask(n, k):
    import itertools
    # For n=4, k could be small.
    # We can test all combinations of k bits.
    for config in itertools.combinations(range(n * n), k):
        initial_mask = 0
        for cell in config:
            initial_mask |= (1 << cell)
        if not solve_reachability(initial_mask, n, get_all_2x2_masks(n)):
            return False
    return True

for n in range(2, 5):
